import{_ as n,a0 as s,w as a,s as i,ao as l,I as d,x as r,a1 as t,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux 下四种安全删除文件的工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下四种安全删除文件的工具 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下四种安全删除文件的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下四种安全删除文件的工具 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150324 4 Tools to Securely Delete Files from Linux","title":"Linux 下四种安全删除文件的工具","tag":"201505","desc":""},"relativePath":"201505/20150324 4 Tools to Securely Delete Files from Linux.md","filePath":"[post].md"}'),u={name:"201505/20150324 4 Tools to Securely Delete Files from Linux.md"};function m(c,e,h,x,f,L){const o=s("Link");return a(),i("div",null,[e[13]||(e[13]=l(`<h1 id="linux-下四种安全删除文件的工具" tabindex="-1">Linux 下四种安全删除文件的工具 <a class="header-anchor" href="#linux-下四种安全删除文件的工具" aria-label="Permalink to “Linux 下四种安全删除文件的工具”">​</a></h1><p>任何一个普通水平的计算机用户都知道，从计算机系统中删除的任意数据都可以稍后通过一些努力恢复出来。当你不小心删除了你的重要数据时，这是一个不错的方案。但是大多数情况，你不希望你的隐私数据被轻易地恢复。不论何时，我们删除的任意文件，操作系统删除的仅仅是对特定数据的索引。这就意味着，数据仍然保存在磁盘的某块地方，这种方法是不安全的，任何一个聪明的计算机黑客可以使用各种不错的数据恢复工具来恢复你删除的数据。Linux 用户利用我们都知晓的 &quot;rm&quot; 命令来从他们的操作系统中删除数据，但是 &quot;rm&quot; 命令也是像上面说的那样删除文件。从这个命令删除的数据也可以使用特殊的文件恢复工具恢复。</p><p>让我们看看怎样安全并完整地从你的 Linux 系统中删除文件或者文件夹。以下提到的工具可以完全地删除数据，因此那些恢复工具很难找到真实数据的痕迹然后恢复它。</p><h3 id="secure-delete" tabindex="-1">Secure-Delete <a class="header-anchor" href="#secure-delete" aria-label="Permalink to “Secure-Delete”">​</a></h3><p>Secure-Delete 是一组为 Linux 操作系统而生的工具集合，他们为永久删除文件提供了先进的技术支持。一旦 Secure-Delete 安装在各种 Linux 系统上，就提供了如下的四个命令：</p><ul><li>srm</li><li>smem</li><li>sfill</li><li>sswap</li></ul><p>在 ubuntu 的终端中运行如下命令安装此工具：</p><pre><code>sudo apt-get install secure-delete
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/secure-delete.png" alt="secure delete"></p><p>在 RHEL，Fedora 或者 Centos 中运行如下命令安装此工具：</p><pre><code> sudo yum install secure-delete
</code></pre><p>“<strong>srm</strong>” 命令的工作方式和 &quot;rm&quot; 命令类似，但是它不仅仅是删除文件，它首先使用一些随机的数据重写数次文件，然后彻底地删除此文件。这个命令的语法是相当地简单，仅仅指定要删除的文件或者目录，然后它会负责此任务。</p><pre><code>sudo srm  /home/aun/Documents/xueo/1.png
</code></pre><p>&quot;<strong>sfill</strong>&quot; 检测在指定的分区或者目录被标记为空闲或者可用的空间，然后使用它自身的算法用一些随机数据填充。因此它保证了在此分区没有可以恢复的文件或者文件夹。</p><pre><code>sudo sfill /home
</code></pre><p>&quot;<strong>sswap</strong>&quot; 命令用来安全地清除你的交换分区。交换分区用来存放运行程序的数据。首先我们需要运行如下命令来找到你的交换分区。</p><pre><code>cat /proc/swaps
</code></pre><p>如下是上述命令的输出示例：</p><pre><code>aun@eagle:~$ cat /proc/swaps
Filename                Type        Size    Used    Priority
/dev/sda5                               partition    2084860    71216    -1
</code></pre><p>从现在起，你可以看到你的交换分区设置在哪个分区，然后使用如下命令安全地清除。替换 &quot;/dev/sda5&quot; 部分为你的交换分区名字。</p><pre><code>sudo sswap /dev/sda5
</code></pre><p>“<strong>smem</strong>” 用来清理在内存中的内容，虽然当系统重启或者关机时会清理随机存取存储器（RAM）中的内容，但是内存中仍然会保留一些数据的残留痕迹。这个命令提供安全的内存清理，简单地在终端中运行 smem 命令即可。</p><pre><code>smem
</code></pre><h3 id="shred" tabindex="-1">Shred <a class="header-anchor" href="#shred" aria-label="Permalink to “Shred”">​</a></h3><p>&quot;shred&quot; 命令以一种不可恢复的方式来销毁文件或者文件夹的内容。它使用随机生成的数据模式来持续覆写文件，因此很难恢复任意的被销毁的数据，即使是那些黑客或者窃贼使用高水平的数据恢复工具或者设备。Shred 默认安装在所有 Linux 发行版中，如果你想，你可以运行如下命令来找到它的安装目录：</p><pre><code>aun@eagle:~$  whereis shred

shred: /usr/bin/shred /usr/share/man/man1/shred.1.gz
</code></pre><p>使用 shred 工具运行如下命令来删除文件：</p><pre><code>shred /home/aun/Documents/xueo/1.png
</code></pre><p>使用 shred 运行如下命令来删除任意的分区，用你期望的分区来替换分区名字。</p><pre><code>shred /dev/sda5
</code></pre><p>Shred 默认情况下使用随机内容重写数据 25 次。如果你想它重写文件更多次数，可以使用 &quot;shred -n&quot; 选项来简单地指定你所期望的次数。</p><pre><code>shred -n 100 filename
</code></pre><p>如果你想在重写后截断或者删除文件，使用 &quot;shred -u&quot; 选项：</p><pre><code>shred -u filename
</code></pre><h3 id="dd" tabindex="-1">dd <a class="header-anchor" href="#dd" aria-label="Permalink to “dd”">​</a></h3><p>这个命令起初是用于磁盘克隆的。它用于将一个分区或者一个磁盘复制到另一个分区或者磁盘。但是它还可用于安全地清除硬盘或者分区的内容。运行如下命令使用随机数据来重写你的当前数据。你不需要安装 dd 命令，所有的 Linux 分发版都已经包含了此命令。</p><pre><code>sudo dd if=/dev/random of=/dev/sda
</code></pre><p>你也可以覆写磁盘或者分区中的内容，只需要简单地将所有替换为 “zero”。</p><pre><code>sudo dd if=/dev/zero of=/dev/sda
</code></pre><h3 id="wipe" tabindex="-1">Wipe <a class="header-anchor" href="#wipe" aria-label="Permalink to “Wipe”">​</a></h3><p>Wipe 起初开发的目的是从磁性介质中安全地擦除文件。这个命令行工具使用特殊的模式来重复地写文件。它使用 fsync() 调用和/或 O_SYNC 位来强制访问磁盘，并且使用 Gutmann 算法来重复地写。你可以使用此命令删除单个文件、文件夹或者整个磁盘的内容，但是使用 wipe 命令来删除整个磁盘的模式会耗费大量的时间。另外，安装和使用这个工具相当容易。</p><p>在 ubuntu 的终端中运行如下命令来安装 wipe。</p><pre><code>sudo aptitude install wipe
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/wipe.png" alt="Wipe Linux"></p><p>使用如下命令在 Redhat Linux，Centos 或者 Fedora 中安装 Wipe：</p><pre><code>sudo yum install wipe
</code></pre><p>一旦安装完成，在终端中运行如下命令来获得完整的可用选项列表：</p><pre><code>man wipe
</code></pre><p>删除任意文件或者目录：</p><pre><code>wipe filename
</code></pre><p>运行如下命令来安全地移除 tmp 分区：</p><pre><code>wipe -r /tmp
</code></pre><p>使用如下的命令来删除完整分区的内容（替换分区名字为你所期望的分区）。</p><pre><code>  wipe /dev/sda1
</code></pre><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h3><p>我们期望这篇文章对你有帮助，你的数据隐私是有决定性意义的，在你的系统中安装这些安全的删除工具对你来说非常重要，因此你可以删除你的隐私数据而不用担心它们被轻易地恢复。上面提到的所有工具都是相当轻量的，它们只需要耗费最低的系统资源来运行，并且无论如何也不会影响你的系统性能。享受它们带来的便利吧！</p><hr>`,57)),d("p",null,[e[1]||(e[1]=r("via: ",-1)),t(o,{href:"http://linoxide.com/security/delete-files-permanatly-linux/"},{default:p(()=>[...e[0]||(e[0]=[r("http://linoxide.com/security/delete-files-permanatly-linux/",-1)])]),_:1})]),d("p",null,[e[5]||(e[5]=r("作者：",-1)),t(o,{href:"http://linoxide.com/author/arunrz/"},{default:p(()=>[...e[2]||(e[2]=[r("Aun Raza",-1)])]),_:1}),e[6]||(e[6]=r(" 译者：",-1)),t(o,{href:"https://github.com/dbarobin"},{default:p(()=>[...e[3]||(e[3]=[r("dbarobin",-1)])]),_:1}),e[7]||(e[7]=r(" 校对：",-1)),t(o,{href:"https://github.com/wxy"},{default:p(()=>[...e[4]||(e[4]=[r("wxy",-1)])]),_:1})]),d("p",null,[e[10]||(e[10]=r("本文由 ",-1)),t(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[8]||(e[8]=[r("LCTT",-1)])]),_:1}),e[11]||(e[11]=r(" 原创翻译，",-1)),t(o,{href:"http://linux.cn/"},{default:p(()=>[...e[9]||(e[9]=[r("Linux中国",-1)])]),_:1}),e[12]||(e[12]=r(" 荣誉推出",-1))])])}const w=n(u,[["render",m]]);export{b as __pageData,w as default};
